  headers?: HeadersInit;

  /**
   * RFC 9457 `type`: URI reference that identifies the problem type. Used when `problemDetails` is enabled.
   */
  type?: string;

  /**
   * RFC 9457 `instance`: URI reference that identifies this occurrence of the problem.
   */
  instance?: string;

  /**
   * @deprecated use `status`
   */
  statusCode?: number;

  /**
   * @deprecated use `statusText`
   */
  statusMessage?: string;
}

export type ErrorDetails = (Error & { cause?: unknown }) | HTTPError | ErrorInput;

export interface ErrorBody<DataT = unknown> {
  /**
   * HTTP status code in range [200...599]
